function wirePanelDividers(){if(state.package==='classic')return;for(let i=0;i<charts.length-1;i++){const a=charts[i],b=charts[i+1],divider=el('div','panel-divider');divider.setAttribute('role','separator');divider.setAttribute('aria-label','Resize chart panels');divider.setAttribute('aria-orientation','horizontal');divider.tabIndex=0;a.wrap.after(divider);let start=null;const resize=delta=>{const total=a.wrap.clientHeight+b.wrap.clientHeight,next=Math.max(130,Math.min(total-130,a.wrap.clientHeight+delta));const weight=(a.panel.height||1)+(b.panel.height||1);a.panel.height=next/total*weight;b.panel.height=(total-next)/total*weight;a.wrap.style.flex=String(a.panel.height);b.wrap.style.flex=String(b.panel.height);drawAll();};divider.addEventListener('pointerdown',event=>{start=event.clientY;divider.setPointerCapture(event.pointerId)});divider.addEventListener('pointermove',event=>{if(start===null)return;const delta=event.clientY-start;start=event.clientY;resize(delta)});divider.addEventListener('pointerup',()=>{start=null;persist()});divider.addEventListener('pointercancel',()=>start=null);divider.addEventListener('keydown',event=>{if(['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();resize(event.key==='ArrowUp'?-15:15);persist()}});}}
